            content: optionalContent(params.verifications),
            label: 'Model verification',
            providerItemId,
            status: 'completed',
            type: 'system',
        };
    }

    return null;
}

module.exports = {
    countUnifiedDiffLines,
    diagnosticEvent,
    normalizeCodexEvent,
    systemEvent,
